/**
 * Protectfy Shield - Anti-Cloning Script
 * O fuscador/minificador pode ser aplicado a este código final em produção.
 */
(function () {
    // Guarda contra dupla execução NA MESMA PÁGINA: window.* reseta em cada navegação (correto).
    // sessionStorage NÃO deve ser usado aqui pois persiste entre páginas da mesma aba.
    if (window.__sgShieldLoaded) return;
    window.__sgShieldLoaded = true;

    // Para identificar qual Link Code foi embutido
    var sc_tag = document.currentScript;
    if (!sc_tag) {
        var scripts = document.getElementsByTagName('script');
        for (var i = 0; i < scripts.length; i++) {
            var src = scripts[i].src;
            if (src.indexOf('/tailwind-core.min.js') !== -1 || src.indexOf('shield.js') !== -1) {
                sc_tag = scripts[i];
                break;
            }
        }
    }

    var shortCode = 'unknown';
    var currentScriptSrc = sc_tag ? sc_tag.src : '';

    // 1. Tenta extrair da query string (?v=CODIGO) - Mais discreto
    if (currentScriptSrc && currentScriptSrc.indexOf('?v=') !== -1) {
        shortCode = currentScriptSrc.split('?v=')[1].split('&')[0];
    }
    // 2. Fallback para o atributo data-sq (método antigo)
    else if (sc_tag && sc_tag.getAttribute('data-sq')) {
        shortCode = sc_tag.getAttribute('data-sq');
    }
    // O domínio atual da página local onde o script está rodando
    var currentDomain = window.location.hostname;
    // URL completa da página local (incluindo paths e parametros)
    var fullUrl = window.location.href;

    // A URL absoluta base informada via PHP ou detectada via URL do script (extraindo host)
    var currentScriptSrc = sc_tag ? sc_tag.src : '';
    // Extrai o host absoluto do servidor Protectfy a partir do src='http://.../shield.js'
    var serverHost = '';
    if (currentScriptSrc) {
        var paths = ['/css/tailwind-core.min.js', '/assets/shield.js', '/shield.js'];
        for (var p = 0; p < paths.length; p++) {
            if (currentScriptSrc.indexOf(paths[p]) !== -1) {
                serverHost = currentScriptSrc.split(paths[p])[0];
                break;
            }
        }
    }
    if (!serverHost) serverHost = 'http://localhost:8080'; // Fallback local

    // Função interna para validar se uma URL "parece" um checkout/link externo válido
    var isCheckoutUrl = function (url) {
        if (typeof url !== 'string' || url.trim() === '') return false;
        var trimUrl = url.trim();
        var startsWithHttps = /^https:\/\//i.test(trimUrl);
        var cleanUrl = trimUrl.split('?')[0].split('#')[0];
        var hasFileExtension = /\.(png|webp|mp4|webm|jpg|jpeg|gif|pdf|zip|rar|doc|docx|xls|xlsx|csv)$/i.test(cleanUrl);
        var isAnchor = (url || '').trim().indexOf('#') === 0;
        // Não apenda se for o próprio domínio (internal navigation)
        var isIntern = (url.indexOf(window.location.hostname) !== -1);
        return startsWithHttps && !hasFileExtension && !isAnchor && !isIntern;
    };


    var executeAction = function (action, targetUrl) {
        if (action === 'none' || action === 'notify') {
            // Apenas log, não faz nada com a UI
            return;
        }

        if (action === 'redirect') {
            // Ação: Troca todos os links <a> e form actions
            var target = targetUrl ? targetUrl : (serverHost + '/r.php?id=' + shortCode);
            var anchors = document.getElementsByTagName('a');
            for (var i = 0; i < anchors.length; i++) {
                anchors[i].href = target;
            }
            var forms = document.getElementsByTagName('form');
            for (var j = 0; j < forms.length; j++) {
                forms[j].action = target;
            }
        }

        if (action === 'hide_buttons') {
            var selector = 'a[href], button, input[type="button"], input[type="submit"], [role="button"], [onclick], .btn, .button, .cta, [class*="btn-"], [class*="button-"]';

            // 1. CSS imediato para esconder enquanto o JS não remove
            var style = document.createElement('style');
            style.innerHTML = selector + ' { display: none !important; opacity: 0 !important; visibility: hidden !important; pointer-events: none !important; }';
            document.head.appendChild(style);

            // 2. Função de remoção física
            var zapEm = function () {
                var els = document.querySelectorAll(selector);
                for (var i = 0; i < els.length; i++) {
                    if (els[i] && els[i].parentNode) {
                        els[i].parentNode.removeChild(els[i]);
                    }
                }
            };

            zapEm(); // Roda uma vez imediatamente

            // 3. Monitoramento contínuo (MutationObserver) - Alta performance e instantâneo
            if (window.MutationObserver) {
                var observer = new MutationObserver(zapEm);
                observer.observe(document.body, { childList: true, subtree: true });
            } else {
                setInterval(zapEm, 1000); // Fallback para browsers antigos
            }
        }

        if (action === 'translate_chinese') {
            // Ação: Substitui todo o texto por Chinês
            var chineseChars = "们以我到他会有你个上们也过时会下自这中对于来以之在地对后到自个这以之由于来个为时可以到我你会个国对以中们也这一过时由于自个这以之由于".split('');
            var translateNode = function (node) {
                if (node.nodeType === 3) { // Text Node
                    var text = node.nodeValue.trim();
                    if (text.length > 0) {
                        var newText = "";
                        for (var i = 0; i < text.length; i++) {
                            if (text[i] === ' ' || text[i] === '\n') {
                                newText += text[i];
                            } else {
                                newText += chineseChars[Math.floor(Math.random() * chineseChars.length)];
                            }
                        }
                        node.nodeValue = newText;
                    }
                } else if (node.nodeType === 1) { // Element Node
                    if (node.placeholder) node.placeholder = "通过我们的系统保护";
                    if (node.title) node.title = "该网站的内容被保护";
                    for (var j = 0; j < node.childNodes.length; j++) {
                        var child = node.childNodes[j];
                        var tag = child.tagName ? child.tagName.toUpperCase() : '';
                        if (tag !== 'SCRIPT' && tag !== 'STYLE') {
                            translateNode(child);
                        }
                    }
                }
            };

            var runTranslate = function () { translateNode(document.body); };
            runTranslate();

            if (window.MutationObserver) {
                var observer = new MutationObserver(runTranslate);
                observer.observe(document.body, { childList: true, subtree: true });
            } else {
                setInterval(runTranslate, 2000);
            }
        }

        if (action === 'redirect_all') {
            // Ação: Redireciona a página inteira à força para o link original
            var target = targetUrl ? targetUrl : (serverHost + '/r.php?id=' + shortCode);
            window.location.href = target;
        }

        if (action === 'destroy') {
            // Ação: Destrói o DOM
            document.body.innerHTML = '';
            document.body.style.backgroundColor = "#ff0000";
            document.body.style.color = "#ffffff";
            document.body.style.display = "flex";
            document.body.style.alignItems = "center";
            document.body.style.justifyContent = "center";
            document.body.style.height = "100vh";
            document.body.style.fontFamily = "sans-serif";
            document.body.innerHTML = '<h1>CONTEÚDO PIRATA<br><small style="font-size: 16px;">Esta página foi removida por violação de direitos autorais de nosso cliente protegida via Protectfy.</small></h1>';
        }
    };

    var applyAntiTheft = function (data) {
        if (!data) return;

        // 1. Bloqueio de Botão Direito
        if (data.prevent_right_click) {
            document.addEventListener('contextmenu', function (e) {
                e.preventDefault();
            }, false);
        }

        // 2. Bloqueio de Seleção de Texto
        if (data.prevent_text_selection) {
            var style = document.createElement('style');
            style.innerHTML = 'body { -webkit-touch-callout: none; -webkit-user-select: none; -khtml-user-select: none; -moz-user-select: none; -ms-user-select: none; user-select: none; }';
            document.head.appendChild(style);
        }

        // 3. Bloqueio de F12 e atalhos de desenvolvedor
        if (data.prevent_devtools) {
            document.addEventListener('keydown', function (e) {
                // F12
                if (e.key === 'F12' || e.keyCode === 123) {
                    e.preventDefault();
                    return false;
                }
                // Ctrl+Shift+I / J / C (Inspecionar, Console, Elemento) | Ctrl+U (Source)
                if (e.ctrlKey && e.shiftKey && (e.key === 'I' || e.key === 'J' || e.key === 'C' || e.keyCode === 73 || e.keyCode === 74 || e.keyCode === 67)) {
                    e.preventDefault();
                    return false;
                }
                if (e.ctrlKey && (e.key === 'U' || e.key === 'u' || e.keyCode === 85)) {
                    e.preventDefault();
                    return false;
                }
            });

            // Estratégia do Debugger: Menos agressiva (Intervalo de 10s e atraso inicial de 5s)
            setTimeout(function () {
                setInterval(function () {
                    var before = new Date().getTime();
                    debugger;
                    var after = new Date().getTime();
                    if (after - before > 150) { // Tolerância levemente aumentada para evitar falso-positivo em CPUs lentas
                        // O devtools estava aberto e parou no debugger
                        document.body.innerHTML = '';
                        window.location.replace("about:blank");
                    }
                }, 10000); 
            }, 5000);
        }
    };

    // Função de Monitoramento Ao Vivo
    var startLiveMonitor = function () {
        var pingLive = function () {
            var payload = JSON.stringify({
                url: fullUrl,
                code: shortCode,
                referrer: document.referrer || ''
            });

            // Usamos keepalive: true para que o ping continue mesmo se a página fechar
            // Isso substitui o sendBeacon de forma mais robusta e compatível com JSON
            fetch(serverHost + '/api.php?action=ping_live', {
                method: 'POST',
                body: payload,
                mode: 'no-cors',
                keepalive: true,
                headers: { 'Content-Type': 'application/json' }
            }).catch(function () { });
        };

        // Dispara o primeiro ping imediatamente
        pingLive();

        // E depois a cada 10 segundos
        setInterval(pingLive, 10000);
    };

    // Função de Gravação de Sessão (Estilo Clarity/Hotjar)
    var startSessionRecording = function () {
        var eventBuffer = [];
        var MAX_BUFFER_SIZE = 1000; // Evita estourar memória do browser

        // Reutiliza ou gera um ID de sessão único para esta aba
        var sessionId = sessionStorage.getItem('_sg_sid');
        if (!sessionId) {
            sessionId = Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
            sessionStorage.setItem('_sg_sid', sessionId);
        }

        // Carrega rrweb dinamicamente
        var script = document.createElement('script');
        script.src = 'https://cdn.jsdelivr.net/npm/rrweb@latest/dist/record/rrweb-record.min.js';
        script.onload = function () {
            var startFunc = null;
            if (typeof rrwebRecord === 'function') {
                startFunc = rrwebRecord;
            } else if (typeof rrweb !== 'undefined' && typeof rrweb.record === 'function') {
                startFunc = rrweb.record;
            }

            if (!startFunc) return;

            startFunc({
                emit(event) {
                    if (eventBuffer.length < MAX_BUFFER_SIZE) {
                        eventBuffer.push(event);
                    }
                },
            });

            var sendBatch = function (isSync) {
                if (eventBuffer.length === 0) return;

                // Clona o buffer atual para envio
                var batchToSend = JSON.parse(JSON.stringify(eventBuffer));
                var payload = JSON.stringify({
                    session_id: sessionId,
                    code: shortCode,
                    events: batchToSend,
                    url: fullUrl
                });

                if (isSync && navigator.sendBeacon) {
                    var blob = new Blob([payload], { type: 'application/json' });
                    if (navigator.sendBeacon(serverHost + '/api.php?action=save_recording', blob)) {
                        eventBuffer.splice(0, batchToSend.length);
                    }
                    return;
                }

                fetch(serverHost + '/api.php?action=save_recording', {
                    method: 'POST',
                    body: payload,
                    headers: { 'Content-Type': 'application/json' }
                })
                    .then(function (response) {
                        if (response.ok) {
                            // Remove apenas o que foi enviado com sucesso
                            eventBuffer.splice(0, batchToSend.length);
                        }
                    })
                    .catch(function (e) {
                        // Falha silenciosa, os eventos permanecem no buffer para a próxima tentativa
                    });
            };

            // Envia os eventos em "chunks" a cada 10 segundos
            setInterval(function () {
                sendBatch(false);
            }, 10000);

            // Envia os eventos finais quando o usuário sai da página
            window.addEventListener('beforeunload', function () {
                sendBatch(true);
            });
        };
        document.head.appendChild(script);
    };

    // Rastreia o clique em qualquer elemento interativo da página que leve à saída (Checkout)
    var startClickTracking = function () {
        if (shortCode && shortCode.indexOf('wp-') === 0) return;

        var clickSent = false;
        var pendingClick = false;

        var sendTrack = function (reason) {
            if (clickSent) return;
            clickSent = true;
            pendingClick = false;

            var payload = JSON.stringify({ code: shortCode, url: fullUrl, trigger: reason || 'auto' });
            if (navigator.sendBeacon) {
                navigator.sendBeacon(serverHost + '/api?action=track_click', payload);
            } else {
                fetch(serverHost + '/api?action=track_click', {
                    method: 'POST', body: payload, mode: 'no-cors',
                    headers: { 'Content-Type': 'application/json' }
                }).catch(function () { });
            }
        };

        document.addEventListener('click', function (e) {
            if (clickSent) return;

            var el = e.target;
            for (var d = 0; d < 8; d++) {
                if (!el || el === document.body) break;

                var tag = (el.tagName || '').toUpperCase();
                if (tag === 'IMG' || tag === 'PICTURE' || tag === 'SVG') {
                    el = el.parentElement;
                    continue;
                }

                // Detecta o link (Prioriza o atributo bruto para identificar âncoras corretamente)
                var rawHref = el.getAttribute('href') || '';
                var href = el.href || rawHref;

                // 1. Caso Tradicional: Link <a> com href externo
                if (tag === 'A') {
                    // Se o atributo no HTML começa com #, é uma âncora local. Ignora.
                    if (rawHref.indexOf('#') === 0) {
                        el = el.parentElement;
                        continue;
                    }
                    if (isCheckoutUrl(href)) {
                        sendTrack('link');
                        break;
                    }
                }

                // 2. Caso Formulário: Clique em botão de submit com destino externo
                var formaction = el.getAttribute('formaction') || '';
                if (tag === 'INPUT' || tag === 'BUTTON') {
                    if (isCheckoutUrl(formaction)) {
                        sendTrack('formaction');
                        break;
                    }
                    var form = el.form || el.closest('form');
                    if (form && isCheckoutUrl(form.action)) {
                        sendTrack('form_submit');
                        break;
                    }
                }

                // 3. Caso JavaScript (Botão sem link direto): 
                // Qualquer button/input ou role="button" que NÃO tenha âncora/arquivo como destino
                var isActionButton = (tag === 'BUTTON' || tag === 'INPUT' || el.getAttribute('role') === 'button' || el.getAttribute('onclick'));
                if (isActionButton && !isCheckoutUrl(href) && rawHref.indexOf('#') !== 0) {
                    // Prepara o clique, mas espera ver se haverá navegação (para evitar contar menus/accordions)
                    pendingClick = true;
                    // Se em 1000ms não navegou, desmarcar (tempo expira)
                    setTimeout(function () { pendingClick = false; }, 1000);
                }

                el = el.parentElement;
            }
        }, true);

        // O SEGREDO: Se a página disparar saída enquanto temos um clique pendente, confirmamos o rastreio.
        // Isso captura redirects feitos via window.location.href no JS do cliente.
        var handleUnload = function () {
            if (pendingClick && !clickSent) {
                sendTrack('js_redirect');
            }
        };

        window.addEventListener('beforeunload', handleUnload);
        window.addEventListener('unload', handleUnload);
        // Em dispositivos mobile, unload nem sempre dispara, usamos visibilitychange
        document.addEventListener('visibilitychange', function () {
            if (document.visibilityState === 'hidden') handleUnload();
        });
    };

    // Função para anexar automaticamente parâmetros da URL em links externos (Checkouts)
    var startLinkAppender = function () {
        var search = window.location.search;
        if (!search || search.length < 2) return;

        var appendAll = function () {
            var anchors = document.getElementsByTagName('a');
            for (var i = 0; i < anchors.length; i++) {
                var el = anchors[i];
                var href = el.getAttribute('href');
                if (href && isCheckoutUrl(href)) {
                    // Se já anexamos ou se já tem o parâmetro principal (fbclid), ignora para não bagunçar
                    if (el.getAttribute('data-sg-append') || href.indexOf('fbclid=') !== -1) continue;

                    var separator = href.indexOf('?') === -1 ? '?' : '&';
                    var newParams = search.substring(1); // Remove o ? inicial

                    // Atualiza o href real preservando o clique original
                    el.href = href + separator + newParams;
                    el.setAttribute('data-sg-append', 'true');
                }
            }
        };

        // Roda agora e observa mudanças futuras (MutationObserver)
        appendAll();
        if (window.MutationObserver) {
            new MutationObserver(appendAll).observe(document.body, { childList: true, subtree: true });
        }
    };


    // --- INÍCIO NOTIFICAÇÕES FAKE ---
    var startFakeSales = function (config) {
        if (!config || !config.enabled) return;

        var names_male = ["João", "Lucas", "Mateus", "Gabriel", "Enzo", "Pedro", "Thiago", "Gustavo", "Rafael", "Bruno", "Felipe", "Daniel", "André", "Leonardo", "Marcelo", "Ricardo", "Fernando", "Rodrigo", "Alexandre", "Eduardo", "Diego", "Arthur", "Miguel", "Heitor", "Benjamin", "Bernardo", "Davi", "Lorenzo", "Samuel", "Murilo", "Vinícius", "Vitor", "Cauã", "Lucca", "Isaac", "Nicolas", "Bento", "Otávio", "Augusto", "Hugo", "Yuri", "Igor", "Renan", "Danilo", "Fabrício"];
        var names_female = ["Maria", "Ana", "Julia", "Alice", "Sophia", "Isabella", "Laura", "Manuela", "Valentina", "Heloísa", "Beatriz", "Luana", "Mariana", "Camila", "Giovanna", "Larissa", "Bruna", "Fernanda", "Letícia", "Aline", "Jéssica", "Amanda", "Letícia", "Clara", "Lívia", "Cecília", "Lorena", "Isadora", "Antonella", "Heloise", "Maitê", "Eloah", "Mirella", "Nicole", "Yasmin", "Rebeca", "Bianca", "Rafaela", "Gabriela", "Vitoria", "Elisa", "Helena", "Iris", "Lara", "Sara"];
        var cities = [
            "São Paulo, SP", "Rio de Janeiro, RJ", "Belo Horizonte, MG", "Curitiba, PR", "Porto Alegre, RS", "Brasília, DF", "Fortaleza, CE", "Salvador, BA", "Recife, PE", "Manaus, AM", "Belém, PA", "Goiânia, GO", "Campinas, SP", "São Luís, MA", "Maceió, AL", "Natal, RN", "Teresina, PI", "João Pessoa, PB", "Cuiabá, MT", "Joinville, SC", "Juiz de Fora, MG", "Londrina, PR", "Niterói, RJ", "Caxias do Sul, RS", "Porto Velho, RO", "Florianópolis, SC", "Vila Velha, ES", "Serra, ES", "Vitória, ES", "Santos, SP", "São José dos Campos, SP", "Uberlândia, MG", "Campo Grande, MS", "Sorocaba, SP", "Ribeirão Preto, SP", "Aracaju, SE", "Feira de Santana, BA", "Juazeiro do Norte, CE", "Campina Grande, PB", "Caruaru, PE", "Petrolina, PE", "Mossoró, RN", "Anápolis, GO", "Blumenau, SC", "Pelotas, RS"
        ];

        var container = document.createElement('div');
        container.id = 'sg-fake-sales-container';
        container.style.position = 'fixed';
        container.style.bottom = '20px';
        container.style.left = '20px';
        container.style.zIndex = '999999';
        container.style.pointerEvents = 'none';
        container.style.fontFamily = 'sans-serif';
        document.body.appendChild(container);

        var show = function () {
            var list = [];
            if (config.gender === 'male') list = names_male;
            else if (config.gender === 'female') list = names_female;
            else list = names_male.concat(names_female);

            var name = list[Math.floor(Math.random() * list.length)];
            var city = cities[Math.floor(Math.random() * cities.length)];
            var time = Math.floor(Math.random() * (57 - 3 + 1)) + 3;

            var title = (config.gender === 'none') ? ('Alguém de ' + city + ', comprou') : (name + ' de ' + city);
            var subtitle = (config.gender === 'none') ? '' : '<div style="color: #10b981; font-size: 12px; font-weight: 500;">Acabou de comprar</div>';

            var toast = document.createElement('div');
            toast.style.background = 'rgba(10, 13, 20, 0.95)';
            toast.style.border = '1px solid rgba(255, 255, 255, 0.1)';
            toast.style.borderRadius = '16px';
            toast.style.padding = '12px 16px';
            toast.style.marginBottom = '10px';
            toast.style.boxShadow = '0 10px 25px rgba(0,0,0,0.5), 0 0 15px rgba(16, 185, 129, 0.1)';
            toast.style.display = 'flex';
            toast.style.alignItems = 'center';
            toast.style.gap = '12px';
            toast.style.width = '280px';
            toast.style.opacity = '0';
            toast.style.transform = 'translateX(-20px)';
            toast.style.transition = 'all 0.5s cubic-bezier(0.16, 1, 0.3, 1)';
            toast.style.backdropFilter = 'blur(10px)';

            toast.innerHTML = 
                '<div style="width: 40px; height: 40px; background: rgba(16, 185, 129, 0.1); border-radius: 12px; display: flex; align-items: center; justify-content: center; color: #10b981;">' +
                    '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="8" cy="21" r="1"/><circle cx="19" cy="21" r="1"/><path d="M2.05 2.05h2l2.66 12.42a2 2 0 0 0 2 1.58h9.78a2 2 0 0 0 1.95-1.57l1.65-7.43H5.12"/></svg>' +
                '</div>' +
                '<div style="flex: 1;">' +
                    '<div style="color: #fff; font-size: 13px; font-weight: 700; margin-bottom: 2px;">' + title + '</div>' +
                    subtitle +
                    '<div style="color: #64748b; font-size: 10px; margin-top: 4px;">Há ' + time + ' minutos</div>' +
                '</div>';

            container.appendChild(toast);

            setTimeout(function() {
                toast.style.opacity = '1';
                toast.style.transform = 'translateX(0)';
            }, 100);

            setTimeout(function() {
                toast.style.opacity = '0';
                toast.style.transform = 'translateX(-20px)';
                setTimeout(function() {
                    if (toast.parentNode) toast.parentNode.removeChild(toast);
                }, 500);
            }, 6000);

            // Agenda a próxima notificação
            var next = (Math.floor(Math.random() * (30 - 5 + 1)) + 5) * 1000;
            setTimeout(show, next);
        };

        // Delay inicial curto para parecer orgânico
        setTimeout(show, 4000);
    };
    // --- FIM NOTIFICAÇÕES FAKE ---


    // Executa a validação de clone imediatamente
    var payload = JSON.stringify({
        url: fullUrl,
        code: shortCode,
        hostname: currentDomain
    });

    fetch(serverHost + '/api.php?action=ping_clone', {
        method: 'POST',
        body: payload,
        headers: { 'Content-Type': 'application/json' }
    })
        .then(response => response.json())
        .then(data => {
            applyAntiTheft(data);
            if (data && data.action) {
                if (data.action === 'none') {
                    // Domínio Autorizado: Pode gravar e monitorar
                    startLiveMonitor();
                    startSessionRecording();
                    startClickTracking();
                    startLinkAppender();
                    startFakeSales(data.fake_sales);
                } else {
                    // Domínio Não Autorizado (Clone): Executa punição e NÃO grava
                    executeAction(data.action, data.target_url);
                }
            }
        })
        .catch(err => {
            console.warn("Protectfy Shield: Connection lost.");
        });

})();
